package phase6fdloader

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"io"
)

// StartupBinding is generated by the loader after validating the outer v2
// envelope, then sealed in FD5. It contains no caller-provided FD contents.
type StartupBinding struct {
	Protocol    string `json:"protocol"`
	RunID       string `json:"run_id"`
	Nonce       string `json:"nonce"`
	ContainerID string `json:"container_id"`
	Target      string `json:"target"`
}

func (b StartupBinding) Validate(hostname string) error {
	if protocol := ControlStartupProtocol(b.Target); protocol == "" || b.Protocol != protocol || !lowerHex(b.RunID, 32) || !lowerHex(b.Nonce, 32) || !lowerHex(b.ContainerID, 64) || !lowerHex(hostname, 12) || b.ContainerID[:12] != hostname {
		return ErrInvalid
	}
	return nil
}

// ReadFrame never buffers bytes belonging to a subsequent frame. EOF is
// deliberately enforced separately for the one final operator reply.
func ReadFrame(r io.Reader, max int) ([]byte, error) {
	var h [4]byte
	if r == nil || max < 1 {
		return nil, ErrInvalid
	}
	if _, e := io.ReadFull(r, h[:]); e != nil {
		return nil, ErrInvalid
	}
	n := binary.BigEndian.Uint32(h[:])
	if n == 0 || uint64(n) > uint64(max) {
		return nil, ErrInvalid
	}
	b := make([]byte, int(n))
	if _, e := io.ReadFull(r, b); e != nil {
		clear(b)
		return nil, ErrInvalid
	}
	return b, nil
}
func WriteFrame(w io.Writer, b []byte, max int) error {
	if w == nil || len(b) == 0 || len(b) > max {
		return ErrInvalid
	}
	var h [4]byte
	binary.BigEndian.PutUint32(h[:], uint32(len(b)))
	for _, part := range [][]byte{h[:], b} {
		for len(part) > 0 {
			n, e := w.Write(part)
			if e != nil || n <= 0 || n > len(part) {
				return ErrInvalid
			}
			part = part[n:]
		}
	}
	return nil
}

// DecodeCanonical rejects unknown, duplicate, omitted and noncanonical fields.
func DecodeCanonical(b []byte, v any) error {
	d := json.NewDecoder(bytes.NewReader(b))
	d.DisallowUnknownFields()
	if d.Decode(v) != nil {
		return ErrInvalid
	}
	out, e := json.Marshal(v)
	if e != nil || !bytes.Equal(b, out) {
		return ErrInvalid
	}
	return nil
}
